import json
from collections import Counter

block = [
    [5, 5, 7],
    [7, 5, 7],
    [7, 5, 7]
]

def count_components_with_details(color, block):
    """Count connected components for a given color using 8-connectivity"""
    visited = set()

    for br in range(3):
        for bc in range(3):
            if block[br][bc] == color and (br, bc) not in visited:
                # Start BFS to find component
                queue = [(br, bc)]
                component_cells = []
                while queue:
                    curr = queue.pop(0)
                    if curr in visited:
                        continue
                    visited.add(curr)
                    component_cells.append(curr)

                    # Check 8 neighbors
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = curr[0] + dr, curr[1] + dc
                            if 0 <= nr < 3 and 0 <= nc < 3:
                                if block[nr][nc] == color and (nr, nc) not in visited:
                                    queue.append((nr, nc))

    total_cells = sum(1 for i in range(3) for j in range(3) if block[i][j] == color)
    num_comps = len(visited)
    return num_comps, list(component_cells), total_cells

colors = set(c for row in block for c in row) - {0}
